definition.raw:
\label{definition of homogeneous}{\rm
(i) Let $V$ be a finite relational vocabulary and $\mathcal{M}$ a $V$-structure. We call $\mathcal{M}$ {\em homogeneous}
if for all finite substructures $\mathcal{A}$ and $\mathcal{B}$ of $\mathcal{M}$, every isomorphism from $\mathcal{A}$ to $\mathcal{B}$ can be extended to an
automorphism of $\mathcal{M}$.\\
(ii) We say that a structure $\mathcal{M}$, with any vocabulary, is {\em $\omega$-homogeneous} 
if whenever $n < \omega$,
$a_1, \ldots, a_n, a_{n+1}, b_1, \ldots, b_n \in M$ and $\mathrm{tp}_\mathcal{M}(a_1, \ldots, a_n) = \mathrm{tp}_\mathcal{M}(b_1, \ldots, b_n)$,
then there is $b_{n+1} \in M$ such that $\mathrm{tp}_\mathcal{M}(a_1, \ldots, a_{n+1}) = \mathrm{tp}_\mathcal{M}(b_1, \ldots, b_{n+1})$.
}

\label{definition of trivial dependence}{\rm
Let $T$ be a complete simple theory.\\
(i) We say that  $T$ has {\em trivial dependence} if, whenever $\mathcal{M} \models T$,
$A, B, C_1, C_2 \subseteq M^{\mathrm{eq}}$ and $A \underset{B}{\raisebox{-2pt}[5pt][0pt]{$\smile$} 
\hspace*{-6.8pt}\raisebox{3pt}[5pt][0pt]{$|$}\hspace*{-6.8pt}
\raisebox{3pt}[5pt][0pt]{$\diagup$} } (C_1 \cup C_2)$, 
then $A \underset{B}{\raisebox{-2pt}[5pt][0pt]{$\smile$} 
\hspace*{-6.8pt}\raisebox{3pt}[5pt][0pt]{$|$}\hspace*{-6.8pt}
\raisebox{3pt}[5pt][0pt]{$\diagup$} } C_i$ for $i = 1$ or $i = 2$.\\
(ii) $T$ (as well as every model of it) is {\em 1-based} if for every $\mathcal{M} \models T$ and all $A, B \subseteq M^{\mathrm{eq}}$, 
$A$ is independent from $B$ over $\mathrm{acl}_{\mathcal{M}^{\mathrm{eq}}}(A) \cap \mathrm{acl}_{\mathcal{M}^{\mathrm{eq}}}(B)$.
}

theorem.raw:
\label{first main result}
Suppose that $\mathcal{M}$ is a structure which is countable, binary, homogeneous, primitive, simple and 1-based.
Then $\mathcal{M}$ is strongly interpretable in a  binary random structure.

lemma.raw:
\label{height and existence of a coordinatizing rank one set}
The following are equivalent:
\begin{itemize}
\item[(1)] $r = 1$.
\item[(2)] There is a $\emptyset$-definable $D \subseteq M^{\mathrm{eq}}$ in which only finitely many sorts are represented
such that $M \subseteq \mathrm{acl}(D)$ and $\mathrm{SU}(d) = 1$ for every $d \in D$.
\end{itemize}

\label{crd is unique up to isomorphism}
If $a, b \in M$ and $\mathrm{tp}(a) = \mathrm{tp}(b)$, then $\mathrm{crd}(a)$ and $\mathrm{crd}(b)$ can be ordered as $\bar{a}$ and $\bar{b}$, respectively,
so that $\mathrm{tp}(\bar{a}) = \mathrm{tp}(\bar{b})$.

proposition.raw:
\label{M is definable in Req}
Let `$\approx$' be the $\emptyset$-definable equivalence relation on $M$ defined by $x \approx y$ if and only if $\mathrm{acl}_\mathcal{M}(x) = \mathrm{acl}_\mathcal{M}(y)$.
Then $\mathcal{M} / \nts \approx$ is definable in $\mathcal{R}^{\mathrm{eq}}$  and we can use a formula $\chi(x)$ and bijection $f : \chi(\mathcal{R}^{\mathrm{eq}}) \to M / \nts \approx$
as in Definition~\ref{definition of strong interpretability} with the properties that 
\begin{enumerate}
\item for all $c \in \chi(\mathcal{R}^{\mathrm{eq}})$,
$\mathrm{acl}_{\mathcal{R}^{\mathrm{eq}}}(c) \cap R = \mathrm{crd}(f(c))$ and $\mathrm{acl}_{\mathcal{R}^{\mathrm{eq}}}(c) = \mathrm{acl}_{\mathcal{R}^{\mathrm{eq}}}(\mathrm{crd}(f(c)))$, 

\item for all $c, c' \in \chi(\mathcal{R}^{\mathrm{eq}})$, $c = c'$ if and only if $\mathrm{crd}(f(c)) = \mathrm{crd}(f(c'))$, and

\item $c \in \mathrm{dcl}_{\mathcal{R}^{\mathrm{eq}}}(\mathrm{acl}_{\mathcal{R}^{\mathrm{eq}}}(c) \cap R)$ for all $c \in \chi(\mathcal{R}^{\mathrm{eq}})$.
\end{enumerate}

